#include <stdint.h>
#define N 4

static uint8_t head, tail;

static int push(void) {
    uint8_t next = (head + 1) & (N - 1);
    if (next == tail) return 0;
    head = next;
    return 1;
}

int main(void) {
    int ok = 0;
    for (int i = 0; i < 6; i++) ok += push();
    printf("%d\n", ok);
}

